import React, { useState } from "react";

const LeadForm = ({ onAdd }) => {
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
  });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!form.name || !form.email) return alert("Vui lòng điền đủ thông tin!");
    onAdd(form);
    setForm({ name: "", email: "", phone: "" });
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        display: "flex",
        gap: "10px",
        marginBottom: "20px",
        alignItems: "center",
      }}
    >
      <input
        type="text"
        name="name"
        placeholder="Tên lead"
        value={form.name}
        onChange={handleChange}
      />
      <input
        type="email"
        name="email"
        placeholder="Email"
        value={form.email}
        onChange={handleChange}
      />
      <input
        type="tel"
        name="phone"
        placeholder="Số điện thoại"
        value={form.phone}
        onChange={handleChange}
      />
      <button type="submit" style={{ background: "#2563eb", color: "white" }}>
        ➕ Thêm Lead
      </button>
    </form>
  );
};

export default LeadForm;
